import Root from "./2Managing State/PPassingDataDeeply/Simplify"
import {HandleInput as Fundamental} from "./2Managing State/4zBaseConcept"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { useState } from "react"

export default function() {
  const [counter, setCounter] = useState(0)
  const [notin, setNotin] = useState(false)
 return <>
 <button onClick={() => {setNotin(!notin)}}>{notin.toString()}</button>
 {notin ? (<Count setCounter={setCounter} counter={counter}/>) : (<Count setCounter={setCounter} counter={counter} key="2"/>)}
 </>
}

function Count({setCounter, counter}) {
  return <button onClick={() => {setCounter(counter+1)}}>{counter}</button>
}

